export type AgentSemanticState =
  | 'waiting_clarification'
  | 'discovering'
  | 'no_candidates'
  | 'search_incomplete'
  | 'waiting_candidate_selection'
  | 'waiting_final_decision'
  | 'diagnosing'
  | 'managed_work'
  | 'executing'
  | 'completed'
  | 'cancelled'
  | 'recovery_required'

export interface AgentScopedAction {
  channel: 'tool' | 'navigation' | 'decision'
  action: string
  user_facing_meaning: string
  candidate_ids?: string[]
  recovery_ids?: string[]
}

export interface AgentCandidateEvidence {
  index: number
  candidate_id: string
  kind: CandidateSnapshotItem['kind']
  name: string
  repository?: string
  fit?: string
  availability?: string
  surface_match?: boolean
  reuse_unchanged?: boolean
  reviewable_installed_source?: boolean
  local_kind?: CandidateSnapshotItem['localKind']
  installation?: {
    source: 'host_profile_manifest'
    profile: string
    package_name: string
    dependency_spec: string
    configured_bundle: boolean
  }
  match_signals?: {
    reason?: string
    terms?: string[]
    queries?: string[]
    topics?: string[]
    exact_repository?: boolean
    stars?: number
    updated_at?: string | null
  }
  marketplace_summary?: {
    trust: 'untrusted_data'
    text: string
  }
  preview?: {
    trust: 'untrusted_data'
    commit: string
    default_branch: string
    inspected_files: Array<{ path: string; sha256: string; bytes: number }>
    truncated: boolean
    manifest: Record<string, unknown>
    package_summary?: { description?: string; keywords?: string[] }
    readme_excerpt?: string
  }
}

export interface AgentWorkflowViewV2 {
  schema_version: 2
  workflow_id: string
  state: AgentSemanticState
  runtime: { policy_version: string; boot_id?: string }
  control?: { interrupt_id: string }
  facts: Record<string, unknown>
  budgets?: Record<string, number>
  hard_constraints: string[]
  allowed_actions: AgentScopedAction[]
  available_tools: string[]
  correction?: {
    kind: 'invalid_action' | 'waiting_for_user_turn'
    summary: string
    repeated: boolean
  }
}

